WITH unpacked AS (SELECT id, effective_from, tier_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE effective_from BETWEEN '2023-03-17' AND '2025-10-01') SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, DATE_TRUNC('MONTH', effective_from) AS activity_month, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2, COUNT(*) AS event_count FROM unpacked GROUP BY quarter_start, activity_month ORDER BY distinct_ids_2 DESC;
